<?php
/** MixerDecoded product landing-page fields. */
if ( ! defined( 'ABSPATH' ) ) { exit; }
function mdpl_register_page_template( $templates ) { $templates['page-templates/premium-product-landing.php'] = 'Premium Product Landing Page'; return $templates; }
add_filter( 'theme_page_templates', 'mdpl_register_page_template' );
function mdpl_admin_assets( $hook ) { if ( in_array( $hook, array( 'post.php', 'post-new.php' ), true ) ) { wp_enqueue_media(); wp_enqueue_script( 'mdpl-admin', get_template_directory_uri() . '/assets/js/mdpl-admin.js', array( 'jquery' ), '1.0.2', true ); } }
add_action( 'admin_enqueue_scripts', 'mdpl_admin_assets' );
function mdpl_front_assets() { if ( is_page() ) { $page = get_queried_object(); if ( $page && get_page_template_slug( $page->ID ) === 'page-templates/premium-product-landing.php' ) { wp_enqueue_style( 'mdpl-product-landing', get_template_directory_uri() . '/assets/css/product-landing.css', array( 'dashwall-style' ), '1.0.2' ); wp_enqueue_script( 'mdpl-product-landing', get_template_directory_uri() . '/assets/js/product-landing.js', array(), '1.0.2', true ); } } }
add_action( 'wp_enqueue_scripts', 'mdpl_front_assets', 30 );
function mdpl_add_meta_box() { add_meta_box( 'mdpl-product-settings', 'MixerDecoded Product Landing Page Settings', 'mdpl_render_meta_box', 'page', 'normal', 'high' ); }
add_action( 'add_meta_boxes_page', 'mdpl_add_meta_box' );
function mdpl_field( $label, $key, $value, $type = 'text', $extra = '' ) { echo '<p class="mdpl-admin-field"><label for="' . esc_attr( $key ) . '"><strong>' . esc_html( $label ) . '</strong></label>'; if ( 'textarea' === $type ) { echo '<textarea class="widefat" rows="3" id="' . esc_attr( $key ) . '" name="' . esc_attr( $key ) . '">' . esc_textarea( $value ) . '</textarea>'; } else { echo '<input class="widefat" type="' . esc_attr( $type ) . '" id="' . esc_attr( $key ) . '" name="' . esc_attr( $key ) . '" value="' . esc_attr( $value ) . '" ' . $extra . '>'; } echo '</p>'; }
function mdpl_render_meta_box( $post ) { wp_nonce_field( 'mdpl_save_settings', 'mdpl_nonce' ); $get = function( $key ) use ( $post ) { return get_post_meta( $post->ID, '_mdpl_' . $key, true ); }; ?>
<div class="mdpl-admin-wrap"><p>Use the page's Gutenberg editor for the full product description. These settings control the premium landing-page sections around it.</p>
<h3>Hero section</h3><?php mdpl_field( 'Eyebrow / category label', 'mdpl_eyebrow', $get('eyebrow') ); mdpl_field( 'Hero headline (leave blank to use page title)', 'mdpl_headline', $get('headline') ); mdpl_field( 'Short supporting introduction', 'mdpl_subhead', $get('subhead'), 'textarea' ); mdpl_field( 'CTA button text', 'mdpl_cta_text', $get('cta_text') ); mdpl_field( 'CTA destination URL', 'mdpl_cta_url', $get('cta_url'), 'url' ); mdpl_field( 'Image caption (optional)', 'mdpl_image_caption', $get('image_caption') ); mdpl_field( 'Product demonstration video URL (YouTube/Vimeo oEmbed)', 'mdpl_demo_video', $get('demo_video'), 'url' ); mdpl_field( 'Video section heading', 'mdpl_video_heading', $get('video_heading') ); ?>
<p><strong>Hero image</strong><br><input type="hidden" id="mdpl_hero_image" name="mdpl_hero_image" value="<?php echo esc_attr( $get('hero_image') ); ?>"><button type="button" class="button mdpl-select-image" data-target="mdpl_hero_image">Choose hero image</button> <button type="button" class="button mdpl-remove-image" data-target="mdpl_hero_image">Remove</button><span class="mdpl-admin-preview" id="mdpl_hero_image_preview"><?php if ( $get('hero_image') ) echo wp_get_attachment_image( $get('hero_image'), 'thumbnail' ); ?></span></p>
<hr><h3>Product benefits</h3><?php $benefits = $get('benefits'); $benefits = is_array( $benefits ) ? $benefits : array(); for ( $i=0; $i<4; $i++ ) { $b = isset( $benefits[$i] ) ? $benefits[$i] : array(); echo '<div class="mdpl-benefit-admin"><h4>Benefit ' . ($i+1) . '</h4>'; mdpl_field( 'Benefit title', 'mdpl_benefits['.$i.'][title]', isset($b['title']) ? $b['title'] : '' ); mdpl_field( 'Short benefit explanation', 'mdpl_benefits['.$i.'][text]', isset($b['text']) ? $b['text'] : '', 'textarea' ); echo '</div>'; } ?>
<hr><h3>Product description section</h3><?php mdpl_field( 'Section heading', 'mdpl_description_heading', $get('description_heading') ); ?><p>The complete product description is written in the main Gutenberg editor above/below this settings panel. You can use headings, images, lists, tables and video embeds.</p>
<hr><h3>Product gallery</h3><?php mdpl_field( 'Gallery heading', 'mdpl_gallery_heading', $get('gallery_heading') ); ?><input type="hidden" id="mdpl_gallery" name="mdpl_gallery" value="<?php echo esc_attr( implode(',', (array) $get('gallery') ) ); ?>"><button type="button" class="button mdpl-select-gallery">Select gallery images</button><div id="mdpl_gallery_preview" class="mdpl-gallery-admin-preview"><?php foreach ( (array) $get('gallery') as $img_id ) echo wp_get_attachment_image( $img_id, 'thumbnail' ); ?></div>
<hr><h3>Social proof</h3><?php mdpl_field( 'Genuine review excerpt or testing observation', 'mdpl_review_quote', $get('review_quote'), 'textarea' ); mdpl_field( 'Attribution / source', 'mdpl_review_source', $get('review_source') ); ?>
<hr><h3>Pricing and purchase</h3><?php mdpl_field( 'Purchase section heading', 'mdpl_purchase_heading', $get('purchase_heading') ); mdpl_field( 'Price label (e.g. Typical retailer price)', 'mdpl_price_label', $get('price_label') ); mdpl_field( 'Displayed price (optional; manually verify before publishing)', 'mdpl_price_amount', $get('price_amount') ); mdpl_field( 'Pricing note / retailer context', 'mdpl_price_note', $get('price_note'), 'textarea' ); ?>
<hr><h3>Related resources</h3><p><label><input type="checkbox" name="mdpl_show_related" value="1" <?php checked( $get('show_related'), '1' ); ?>> Display related resources section</label></p><?php mdpl_field( 'Related resource content (HTML links allowed)', 'mdpl_related_content', $get('related_content'), 'textarea' ); ?></div>
<?php }
function mdpl_save_meta( $post_id ) { if ( ! isset( $_POST['mdpl_nonce'] ) || ! wp_verify_nonce( sanitize_text_field( wp_unslash( $_POST['mdpl_nonce'] ) ), 'mdpl_save_settings' ) ) return; if ( defined('DOING_AUTOSAVE') && DOING_AUTOSAVE ) return; if ( ! current_user_can( 'edit_page', $post_id ) ) return; $text_keys = array( 'eyebrow','headline','subhead','cta_text','image_caption','description_heading','gallery_heading','review_quote','review_source','purchase_heading','price_label','price_amount','price_note','video_heading' ); foreach ( $text_keys as $key ) { if ( isset( $_POST['mdpl_'.$key] ) ) update_post_meta( $post_id, '_mdpl_'.$key, sanitize_textarea_field( wp_unslash( $_POST['mdpl_'.$key] ) ) ); } if ( isset( $_POST['mdpl_demo_video'] ) ) update_post_meta( $post_id, '_mdpl_demo_video', esc_url_raw( wp_unslash( $_POST['mdpl_demo_video'] ) ) ); if ( isset( $_POST['mdpl_cta_url'] ) ) update_post_meta( $post_id, '_mdpl_cta_url', esc_url_raw( wp_unslash( $_POST['mdpl_cta_url'] ) ) ); if ( isset( $_POST['mdpl_hero_image'] ) ) update_post_meta( $post_id, '_mdpl_hero_image', absint( $_POST['mdpl_hero_image'] ) ); if ( isset( $_POST['mdpl_benefits'] ) && is_array( $_POST['mdpl_benefits'] ) ) { $clean = array(); foreach ( $_POST['mdpl_benefits'] as $b ) { $clean[] = array( 'title' => sanitize_text_field( $b['title'] ?? '' ), 'text' => sanitize_textarea_field( $b['text'] ?? '' ) ); } update_post_meta( $post_id, '_mdpl_benefits', $clean ); } if ( isset( $_POST['mdpl_gallery'] ) ) { $ids = array_filter( array_map( 'absint', explode( ',', sanitize_text_field( wp_unslash( $_POST['mdpl_gallery'] ) ) ) ) ); update_post_meta( $post_id, '_mdpl_gallery', $ids ); } update_post_meta( $post_id, '_mdpl_show_related', isset( $_POST['mdpl_show_related'] ) ? '1' : '0' ); if ( isset( $_POST['mdpl_related_content'] ) ) update_post_meta( $post_id, '_mdpl_related_content', wp_kses_post( wp_unslash( $_POST['mdpl_related_content'] ) ) ); }
add_action( 'save_post_page', 'mdpl_save_meta' );
